//! Sound effects: plays a sound for each `GameEvent` and for changes in beam,
//! energy and prism state, plus looping beam sounds. Presentation only.
//!
//! The sounds are generated by `tools/sfx` (`just sfx`) and embedded in the
//! binary. Pitched sounds stay in the Lydian scale on C, matching the
//! generator; see `docs/design.md`.

use std::sync::Arc;

use bevy::audio::{AudioSinkPlayback, Volume};
use bevy::prelude::*;

use crate::beam::{BeamEnergy, BeamTuning};
use crate::enemy::EnemyKind;
use crate::events::GameEvent;
use crate::powerup::{Abilities, PowerUp};
use crate::prism::PrismFrozen;
use crate::render::{BeamView, MainCamera};

/// Every sound effect. Names match the files `tools/sfx` writes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Reflect)]
pub enum SoundId {
    BeamHum,
    BeamChord,
    BeamStart,
    BeamStop,
    EnemyHit,
    MoteDefeat,
    LensDefeat,
    OrbFire,
    OrbBlocked,
    Bounce,
    WallBump,
    LifeLost,
    Respawn,
    InvulnerabilityEnd,
    RoomReset,
    PickupAppear,
    PickupCollect,
    PickupExpiring,
    AbilitiesLost,
    PrismFreeze,
    PrismUnfreeze,
    EnergyEmpty,
    EnergyFull,
}

macro_rules! sound_files {
    ($($id:ident => $name:literal),* $(,)?) => {
        impl SoundId {
            pub const ALL: &[Self] = &[$(Self::$id),*];

            /// The generated file's name, without extension.
            #[must_use]
            pub const fn name(self) -> &'static str {
                match self {
                    $(Self::$id => $name),*
                }
            }

            /// The embedded WAV data.
            #[must_use]
            pub const fn bytes(self) -> &'static [u8] {
                match self {
                    $(Self::$id => include_bytes!(concat!("../assets/audio/", $name, ".wav"))),*
                }
            }
        }
    };
}

sound_files! {
    BeamHum => "beam_hum",
    BeamChord => "beam_chord",
    BeamStart => "beam_start",
    BeamStop => "beam_stop",
    EnemyHit => "enemy_hit",
    MoteDefeat => "mote_defeat",
    LensDefeat => "lens_defeat",
    OrbFire => "orb_fire",
    OrbBlocked => "orb_blocked",
    Bounce => "bounce",
    WallBump => "wall_bump",
    LifeLost => "life_lost",
    Respawn => "respawn",
    InvulnerabilityEnd => "invulnerability_end",
    RoomReset => "room_reset",
    PickupAppear => "pickup_appear",
    PickupCollect => "pickup_collect",
    PickupExpiring => "pickup_expiring",
    AbilitiesLost => "abilities_lost",
    PrismFreeze => "prism_freeze",
    PrismUnfreeze => "prism_unfreeze",
    EnergyEmpty => "energy_empty",
    EnergyFull => "energy_full",
}

/// Semitone offsets from the root for each degree of the Lydian scale.
pub const LYDIAN: [i32; 7] = [0, 2, 4, 6, 7, 9, 11];

/// Playback speed that shifts a sound up by `degree` steps of the Lydian
/// scale (degree 7 is an octave up).
#[must_use]
pub fn lydian_speed(degree: i32) -> f32 {
    let octave = degree.div_euclid(7);
    let step = LYDIAN[usize::try_from(degree.rem_euclid(7)).unwrap_or(0)];
    // Small whole numbers, exactly representable.
    #[allow(clippy::cast_precision_loss)]
    let semitones = (octave * 12 + step) as f32;
    (semitones / 12.0).exp2()
}

/// The scale degree each power-up's collect chime is raised by. Anti-gravity
/// gets the raised fourth, Lydian's floating colour note.
#[must_use]
pub const fn power_up_degree(power: PowerUp) -> i32 {
    match power {
        PowerUp::RearShot => 0,
        PowerUp::Spread => 1,
        PowerUp::Piercing => 2,
        PowerUp::AntiGravity => 3,
        PowerUp::RapidFire => 4,
    }
}

/// Volume levels, adjusted from the dev tuning panel.
#[derive(Resource, Debug, Clone, PartialEq, Reflect)]
#[reflect(Resource)]
pub struct SoundSettings {
    pub master: f32,
    /// One-shot effects.
    pub effects: f32,
    /// The looping beam hum and chord.
    pub beam: f32,
}

impl Default for SoundSettings {
    fn default() -> Self {
        Self {
            master: 0.8,
            effects: 1.0,
            beam: 0.6,
        }
    }
}

/// Handles for every embedded sound.
#[derive(Resource, Debug, Default)]
pub struct SoundBank(Vec<(SoundId, Handle<AudioSource>)>);

impl SoundBank {
    #[must_use]
    pub fn get(&self, id: SoundId) -> Handle<AudioSource> {
        self.0
            .iter()
            .find(|(i, _)| *i == id)
            .map(|(_, h)| h.clone())
            .unwrap_or_default()
    }
}

/// Sounds requested from the dev panel, played centred.
#[derive(Resource, Debug, Default)]
pub struct Auditions(pub Vec<SoundId>);

/// A sound to play.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Cue {
    pub id: SoundId,
    /// Playback speed, which also shifts pitch.
    pub speed: f32,
    pub volume: f32,
    /// Where it happens, for panning; `None` plays centred.
    pub at: Option<Vec2>,
    /// Seconds to wait before playing.
    pub delay: f32,
}

impl Cue {
    const fn new(id: SoundId) -> Self {
        Self {
            id,
            speed: 1.0,
            volume: 1.0,
            at: None,
            delay: 0.0,
        }
    }

    const fn at(mut self, at: Vec2) -> Self {
        self.at = Some(at);
        self
    }

    const fn speed(mut self, speed: f32) -> Self {
        self.speed = speed;
        self
    }

    const fn volume(mut self, volume: f32) -> Self {
        self.volume = volume;
        self
    }

    const fn delay(mut self, delay: f32) -> Self {
        self.delay = delay;
        self
    }
}

/// Seconds after a mote defeat within which the next one climbs the scale.
pub const COMBO_WINDOW: f32 = 1.2;

/// Chained mote defeats climb the Lydian scale.
#[derive(Resource, Debug, Default, Clone, Copy, PartialEq)]
pub struct KillCombo {
    pub degree: i32,
    /// Seconds since the last mote defeat.
    pub since: f32,
}

/// The sounds for one game event.
#[must_use]
pub fn cues_for(event: GameEvent, combo: &mut KillCombo) -> Vec<Cue> {
    match event {
        GameEvent::EnemyHit { at } => vec![Cue::new(SoundId::EnemyHit).at(at).volume(0.6)],
        GameEvent::EnemyDefeated {
            kind: EnemyKind::Mote,
            at,
        } => {
            combo.degree = if combo.since <= COMBO_WINDOW {
                (combo.degree + 1).min(14)
            } else {
                0
            };
            combo.since = 0.0;
            vec![
                Cue::new(SoundId::MoteDefeat)
                    .at(at)
                    .speed(lydian_speed(combo.degree)),
            ]
        }
        GameEvent::EnemyDefeated {
            kind: EnemyKind::Lens,
            at,
        } => vec![Cue::new(SoundId::LensDefeat).at(at)],
        GameEvent::OrbFired { at } => vec![Cue::new(SoundId::OrbFire).at(at)],
        GameEvent::OrbBlocked { at } => vec![Cue::new(SoundId::OrbBlocked).at(at)],
        GameEvent::Bounced { at, spin } => {
            let speed = 1.0 + 0.06 * f32::from(spin.unsigned_abs());
            vec![Cue::new(SoundId::Bounce).at(at).speed(speed)]
        }
        GameEvent::WallBump { at } => vec![Cue::new(SoundId::WallBump).at(at)],
        GameEvent::LifeLost { at, respawn } => vec![
            Cue::new(SoundId::LifeLost).at(at),
            Cue::new(SoundId::Respawn).at(respawn).delay(0.7),
        ],
        GameEvent::AbilitiesLost => vec![Cue::new(SoundId::AbilitiesLost).delay(0.25)],
        GameEvent::InvulnerabilityEnded { at } => {
            vec![Cue::new(SoundId::InvulnerabilityEnd).at(at)]
        }
        GameEvent::RoomReset => vec![Cue::new(SoundId::RoomReset)],
        GameEvent::PickupDropped { at, .. } => vec![Cue::new(SoundId::PickupAppear).at(at)],
        GameEvent::PickupCollected { power, at } => vec![
            Cue::new(SoundId::PickupCollect)
                .at(at)
                .speed(lydian_speed(power_up_degree(power))),
        ],
        GameEvent::PickupExpiring { at } => vec![Cue::new(SoundId::PickupExpiring).at(at)],
    }
}

/// Distance between the listener's ears. Emitters sit within this of both
/// ears, so rodio's distance falloff never applies and panning stays gentle.
const EAR_GAP: f32 = 1.0;

/// Furthest an emitter is placed from centre (at most `EAR_GAP / 2`).
const MAX_PAN_OFFSET: f32 = 0.4;
const _: () = assert!(MAX_PAN_OFFSET <= EAR_GAP / 2.0);

/// rodio 0.22's spatial panning makes the ear further from the emitter the
/// louder one, so emitters are mirrored to sound on the correct side.
const PAN_SIGN: f32 = -1.0;

/// Volume of sounds two half-screens or more away.
const FAR_GAIN: f32 = 0.35;

/// Emitter x offset and volume for a sound at world x `x` heard from a
/// camera centred on `camera_x` showing `half_width` either side. Sounds
/// pan with screen position and fade once off screen.
#[must_use]
pub fn pan_and_gain(x: f32, camera_x: f32, half_width: f32) -> (f32, f32) {
    let across = (x - camera_x) / half_width.max(1.0);
    let offset = across.clamp(-1.0, 1.0) * MAX_PAN_OFFSET * PAN_SIGN;
    let beyond = (across.abs() - 1.0).clamp(0.0, 1.0);
    (offset, 1.0 - beyond * (1.0 - FAR_GAIN))
}

/// Marks a playing one-shot so tests and tools can find it.
#[derive(Component, Debug, Clone, Copy, PartialEq, Eq)]
pub struct Effect(pub SoundId);

/// A cue waiting for its delay.
#[derive(Component, Debug)]
struct PendingCue {
    cue: Cue,
    timer: Timer,
}

/// The looping beam hum; its volume and pitch follow the beam.
#[derive(Component, Debug)]
pub struct BeamHum;

/// The looping triad heard while the beam splits through the prism.
#[derive(Component, Debug)]
pub struct BeamChord;

#[derive(Debug, Default)]
pub struct SoundPlugin;

impl Plugin for SoundPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<SoundSettings>()
            .register_type::<SoundSettings>()
            .init_resource::<Auditions>()
            .init_resource::<KillCombo>()
            .add_systems(Startup, (load_sounds, spawn_listener).chain())
            .add_systems(Startup, spawn_beam_loops.after(load_sounds))
            .add_systems(
                Update,
                (
                    queue_event_cues,
                    queue_state_cues,
                    queue_auditions,
                    play_pending_cues,
                )
                    .chain(),
            )
            .add_systems(Update, drive_beam_loops);
    }
}

fn load_sounds(mut commands: Commands, mut sources: ResMut<Assets<AudioSource>>) {
    let bank = SoundId::ALL
        .iter()
        .map(|&id| {
            let handle = sources.add(AudioSource {
                bytes: Arc::from(id.bytes()),
            });
            (id, handle)
        })
        .collect();
    commands.insert_resource(SoundBank(bank));
}

fn spawn_listener(mut commands: Commands) {
    commands.spawn((
        Name::new("Audio listener"),
        SpatialListener::new(EAR_GAP),
        Transform::default(),
    ));
}

fn spawn_beam_loops(mut commands: Commands, bank: Res<SoundBank>) {
    let silent = PlaybackSettings::LOOP.with_volume(Volume::SILENT);
    commands.spawn((
        Name::new("Beam hum"),
        BeamHum,
        AudioPlayer(bank.get(SoundId::BeamHum)),
        silent,
    ));
    commands.spawn((
        Name::new("Beam chord"),
        BeamChord,
        AudioPlayer(bank.get(SoundId::BeamChord)),
        silent,
    ));
}

fn queue(commands: &mut Commands, cue: Cue) {
    commands.spawn((
        Name::new(format!("Cue {:?}", cue.id)),
        PendingCue {
            cue,
            timer: Timer::from_seconds(cue.delay, TimerMode::Once),
        },
    ));
}

fn queue_event_cues(
    mut commands: Commands,
    time: Res<Time>,
    mut combo: ResMut<KillCombo>,
    mut events: MessageReader<GameEvent>,
) {
    combo.since += time.delta_secs();
    for &event in events.read() {
        for cue in cues_for(event, &mut combo) {
            queue(&mut commands, cue);
        }
    }
}

/// What the state-driven sounds last saw.
#[derive(Debug, Default, Clone, Copy, PartialEq)]
#[allow(clippy::struct_excessive_bools)]
struct Watched {
    firing: bool,
    needs_release: bool,
    full: bool,
    frozen: bool,
}

/// Sounds for changes in state rather than events: the beam starting and
/// stopping, energy running out or refilling, and the prism freezing.
fn queue_state_cues(
    mut commands: Commands,
    energy: Res<BeamEnergy>,
    tuning: Res<BeamTuning>,
    frozen: Res<PrismFrozen>,
    mut last: Local<Option<Watched>>,
) {
    let now = Watched {
        firing: energy.firing,
        needs_release: energy.needs_release,
        full: energy.current >= tuning.max_energy,
        frozen: frozen.0,
    };
    let Some(before) = last.replace(now) else {
        return;
    };
    let mut cues = Vec::new();
    if now.firing != before.firing {
        cues.push(if now.firing {
            SoundId::BeamStart
        } else {
            SoundId::BeamStop
        });
    }
    if now.needs_release && !before.needs_release {
        cues.push(SoundId::EnergyEmpty);
    }
    if now.full && !before.full {
        cues.push(SoundId::EnergyFull);
    }
    if now.frozen != before.frozen {
        cues.push(if now.frozen {
            SoundId::PrismFreeze
        } else {
            SoundId::PrismUnfreeze
        });
    }
    for id in cues {
        queue(&mut commands, Cue::new(id));
    }
}

fn queue_auditions(mut commands: Commands, mut auditions: ResMut<Auditions>) {
    if auditions.0.is_empty() {
        return;
    }
    for id in auditions.0.drain(..) {
        queue(&mut commands, Cue::new(id));
    }
}

/// Play each cue once its delay is up, panned from the camera's view.
fn play_pending_cues(
    mut commands: Commands,
    time: Res<Time>,
    settings: Res<SoundSettings>,
    bank: Option<Res<SoundBank>>,
    cameras: Query<(&Transform, &Projection), With<MainCamera>>,
    mut pending: Query<(Entity, &mut PendingCue)>,
) {
    let Some(bank) = bank else {
        return;
    };
    let (camera_x, half_width) = cameras.single().map_or((0.0, 960.0), |(t, p)| {
        let half = match p {
            Projection::Orthographic(ortho) => ortho.area.width() / 2.0,
            _ => 960.0,
        };
        (t.translation.x, half)
    });
    for (entity, mut pending) in &mut pending {
        if !pending.timer.tick(time.delta()).is_finished() {
            continue;
        }
        let cue = pending.cue;
        let (offset, gain) = cue
            .at
            .map_or((0.0, 1.0), |at| pan_and_gain(at.x, camera_x, half_width));
        let volume = cue.volume * gain * settings.effects * settings.master;
        commands.entity(entity).despawn();
        commands.spawn((
            Name::new(format!("Sound {:?}", cue.id)),
            Effect(cue.id),
            AudioPlayer(bank.get(cue.id)),
            PlaybackSettings::DESPAWN
                .with_volume(Volume::Linear(volume))
                .with_speed(cue.speed)
                .with_spatial(true),
            Transform::from_xyz(offset, 0.0, 0.0),
        ));
    }
}

/// How fast the beam loops fade in and out (per second).
const BEAM_FADE_RATE: f32 = 25.0;

/// Beam hum pitch: drops by up to 20% as energy falls through the bottom
/// third, as a warning, and lifts slightly with rapid fire.
#[must_use]
pub fn hum_speed(energy: f32, max_energy: f32, rapid_fire: bool) -> f32 {
    let level = (energy / (max_energy.max(1.0) / 3.0)).clamp(0.0, 1.0);
    let boost = if rapid_fire { 1.06 } else { 1.0 };
    (0.8 + 0.2 * level) * boost
}

/// Ease `current` towards `target` at `rate` per second.
#[must_use]
pub fn approach(current: f32, target: f32, rate: f32, dt: f32) -> f32 {
    current + (target - current) * (1.0 - (-rate * dt).exp())
}

fn drive_beam_loops(
    time: Res<Time>,
    settings: Res<SoundSettings>,
    energy: Res<BeamEnergy>,
    tuning: Res<BeamTuning>,
    abilities: Res<Abilities>,
    view: Option<Res<BeamView>>,
    mut hums: Query<&mut AudioSink, (With<BeamHum>, Without<BeamChord>)>,
    mut chords: Query<&mut AudioSink, (With<BeamChord>, Without<BeamHum>)>,
) {
    let dt = time.delta_secs();
    let level = settings.beam * settings.master;
    let split = view.is_some_and(|v| v.split);
    let speed = hum_speed(
        energy.current,
        tuning.max_energy,
        abilities.has(PowerUp::RapidFire),
    );
    let drive = |sink: &mut AudioSink, target: f32| {
        let next = approach(sink.volume().to_linear(), target, BEAM_FADE_RATE, dt);
        sink.set_volume(Volume::Linear(next));
        sink.set_speed(speed);
    };
    for mut sink in &mut hums {
        drive(&mut sink, if energy.firing { level } else { 0.0 });
    }
    for mut sink in &mut chords {
        drive(
            &mut sink,
            if energy.firing && split {
                level * 0.8
            } else {
                0.0
            },
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hero::Hero;
    use crate::hero::Position;
    use bevy::time::TimeUpdateStrategy;
    use std::time::Duration;

    #[test]
    fn every_sound_is_a_wav_with_a_unique_name() {
        let mut names: Vec<_> = SoundId::ALL.iter().map(|id| id.name()).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), SoundId::ALL.len());
        for id in SoundId::ALL {
            let bytes = id.bytes();
            assert_eq!(&bytes[0..4], b"RIFF", "{id:?}");
            assert_eq!(&bytes[8..12], b"WAVE", "{id:?}");
        }
    }

    #[test]
    fn lydian_speeds_climb_the_scale() {
        assert!((lydian_speed(0) - 1.0).abs() < 1e-6);
        assert!((lydian_speed(7) - 2.0).abs() < 1e-5);
        assert!((lydian_speed(3) - (6.0f32 / 12.0).exp2()).abs() < 1e-5);
        let speeds: Vec<f32> = (0..15).map(lydian_speed).collect();
        assert!(speeds.windows(2).all(|w| w[1] > w[0]));
        let degrees: Vec<i32> = PowerUp::ALL.into_iter().map(power_up_degree).collect();
        let mut unique = degrees.clone();
        unique.sort_unstable();
        unique.dedup();
        assert_eq!(unique.len(), degrees.len());
    }

    #[test]
    fn chained_mote_defeats_climb_and_reset_after_a_pause() {
        let mut combo = KillCombo {
            degree: 0,
            since: 10.0,
        };
        let defeat = GameEvent::EnemyDefeated {
            kind: EnemyKind::Mote,
            at: Vec2::ZERO,
        };
        let speeds: Vec<f32> = (0..3)
            .map(|_| cues_for(defeat, &mut combo)[0].speed)
            .collect();
        assert!((speeds[0] - 1.0).abs() < 1e-6);
        assert!(speeds[1] > speeds[0] && speeds[2] > speeds[1]);
        combo.since = COMBO_WINDOW + 0.1;
        assert!((cues_for(defeat, &mut combo)[0].speed - 1.0).abs() < 1e-6);
    }

    #[test]
    fn every_event_has_a_sound() {
        let mut combo = KillCombo::default();
        let at = Vec2::ZERO;
        let events = [
            GameEvent::EnemyHit { at },
            GameEvent::EnemyDefeated {
                kind: EnemyKind::Lens,
                at,
            },
            GameEvent::OrbFired { at },
            GameEvent::OrbBlocked { at },
            GameEvent::Bounced { at, spin: -3 },
            GameEvent::WallBump { at },
            GameEvent::LifeLost { at, respawn: at },
            GameEvent::AbilitiesLost,
            GameEvent::InvulnerabilityEnded { at },
            GameEvent::RoomReset,
            GameEvent::PickupDropped {
                power: PowerUp::Spread,
                at,
            },
            GameEvent::PickupCollected {
                power: PowerUp::AntiGravity,
                at,
            },
            GameEvent::PickupExpiring { at },
        ];
        for event in events {
            assert!(!cues_for(event, &mut combo).is_empty(), "{event:?}");
        }
        let life = cues_for(GameEvent::LifeLost { at, respawn: at }, &mut combo);
        assert!(life[1].delay > 0.0, "respawn follows the loss");
        let fast = cues_for(GameEvent::Bounced { at, spin: 5 }, &mut combo)[0].speed;
        let slow = cues_for(GameEvent::Bounced { at, spin: 0 }, &mut combo)[0].speed;
        assert!(fast > slow);
    }

    #[test]
    fn panning_follows_screen_position_and_fades_off_screen() {
        let (centre, gain) = pan_and_gain(500.0, 500.0, 960.0);
        assert!(centre.abs() < 1e-6);
        assert!((gain - 1.0).abs() < 1e-6);

        let (right, gain) = pan_and_gain(1460.0, 500.0, 960.0);
        assert!((right.abs() - MAX_PAN_OFFSET).abs() < 1e-6);
        assert!((gain - 1.0).abs() < 1e-6, "on screen: full volume");
        let (left, _) = pan_and_gain(-460.0, 500.0, 960.0);
        assert!((left + right).abs() < 1e-6, "mirror images");

        let (_, far) = pan_and_gain(5000.0, 500.0, 960.0);
        assert!((far - FAR_GAIN).abs() < 1e-6);
        let (_, edge) = pan_and_gain(500.0 + 960.0 * 1.5, 500.0, 960.0);
        assert!(edge < 1.0 && edge > FAR_GAIN);
    }

    #[test]
    fn hum_dips_when_low_and_rises_with_rapid_fire() {
        assert!((hum_speed(100.0, 100.0, false) - 1.0).abs() < 1e-6);
        assert!((hum_speed(0.0, 100.0, false) - 0.8).abs() < 1e-6);
        assert!(hum_speed(10.0, 100.0, false) < hum_speed(30.0, 100.0, false));
        assert!(hum_speed(100.0, 100.0, true) > 1.0);
        assert!((approach(0.0, 1.0, 25.0, 1.0) - 1.0).abs() < 1e-6);
        assert!(approach(0.0, 1.0, 25.0, 0.01) < 0.5);
    }

    fn sound_app() -> App {
        let mut app = App::new();
        app.add_plugins((MinimalPlugins, AssetPlugin::default()))
            .init_asset::<Mesh>()
            .init_asset::<ColorMaterial>()
            .init_asset::<AudioSource>()
            .init_resource::<ButtonInput<KeyCode>>()
            .insert_resource(TimeUpdateStrategy::ManualDuration(Duration::from_millis(
                16,
            )))
            .add_plugins((
                crate::SimulationPlugin,
                crate::render::PresentationPlugin,
                SoundPlugin,
            ));
        app.update();
        app
    }

    fn effects(app: &mut App) -> Vec<SoundId> {
        let world = app.world_mut();
        world.query::<&Effect>().iter(world).map(|e| e.0).collect()
    }

    #[test]
    fn events_and_state_changes_play_sounds() {
        let mut app = sound_app();
        assert_eq!(
            app.world().resource::<SoundBank>().0.len(),
            SoundId::ALL.len()
        );
        let loops = {
            let world = app.world_mut();
            world
                .query_filtered::<(), Or<(With<BeamHum>, With<BeamChord>)>>()
                .iter(world)
                .count()
        };
        assert_eq!(loops, 2);

        // A collected pickup plays its chime.
        let hero = {
            let world = app.world_mut();
            world
                .query_filtered::<&Position, With<Hero>>()
                .single(world)
                .unwrap()
                .0
        };
        app.world_mut()
            .spawn(crate::powerup::pickup_bundle(PowerUp::Piercing, hero));
        // Firing starts the beam.
        app.world_mut()
            .resource_mut::<ButtonInput<KeyCode>>()
            .press(KeyCode::Space);
        for _ in 0..3 {
            app.update();
        }
        let played = effects(&mut app);
        assert!(played.contains(&SoundId::PickupCollect), "{played:?}");
        assert!(played.contains(&SoundId::BeamStart), "{played:?}");

        app.world_mut()
            .resource_mut::<Auditions>()
            .0
            .push(SoundId::RoomReset);
        app.update();
        assert!(effects(&mut app).contains(&SoundId::RoomReset));
    }

    #[test]
    fn delayed_cues_wait_their_turn() {
        let mut app = sound_app();
        app.world_mut()
            .resource_mut::<Messages<GameEvent>>()
            .write(GameEvent::LifeLost {
                at: Vec2::ZERO,
                respawn: Vec2::ZERO,
            });
        app.update();
        let played = effects(&mut app);
        assert!(played.contains(&SoundId::LifeLost));
        assert!(!played.contains(&SoundId::Respawn));
        for _ in 0..60 {
            app.update();
        }
        assert!(effects(&mut app).contains(&SoundId::Respawn));
    }
}
